package io.quarkiverse.mcp.server.stdio;

import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Regression test to ensure the stdio transport parent POM description
 * is correctly spelled (no typos like "stanard" instead of "standard").
 */
class StdioPomDescriptionTest {

    @Test
    void pomDescriptionShouldNotContainTypo() throws IOException {
        Path pomPath = Paths.get("pom.xml").toAbsolutePath()
                .getParent().getParent() // go up from runtime to transports/stdio
                .resolve("pom.xml");

        String pomContent = Files.readString(pomPath);

        // Extract the description value
        Pattern descPattern = Pattern.compile("<description>([^<]+)</description>");
        Matcher matcher = descPattern.matcher(pomContent);

        // If no description element exists, that's fine - nothing to check
        if (!matcher.find()) {
            return;
        }

        String description = matcher.group(1);

        // The description should NOT contain the typo "stanard"
        assertFalse(description.contains("stanard"),
                "POM description contains typo 'stanard' instead of 'standard': " + description);

        // If it mentions standard I/O, it should be correctly spelled
        if (description.toLowerCase().contains("input/output")) {
            assertTrue(description.contains("standard input/output")
                    || description.contains("Standard input/output"),
                    "POM description should contain 'standard input/output': " + description);
        }
    }
}
